// Validación y limpieza de datos del profesional
const profesional = $input.first().json;

// Función de validación con IA simulada
function validarConIA(datos) {
  const validaciones = {
    nombre: datos.nombre && datos.nombre.length >= 3,
    email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(datos.email),
    telefono: /^\d{10,15}$/.test(datos.telefono.replace(/\D/g, '')),
    categoria: ['plomeria', 'electricidad', 'construccion', 'pintura', 'jardineria', 'limpieza', 'mecanica', 'otros'].includes(datos.categoria.toLowerCase()),
    experiencia: !datos.experiencia || datos.experiencia >= 0,
    precio: !datos.precio_hora || datos.precio_hora > 0
  };

  const esValido = Object.values(validaciones).every(v => v === true);
  const errores = Object.entries(validaciones)
    .filter(([campo, valido]) => !valido)
    .map(([campo]) => campo);

  return { esValido, errores, validaciones };
}

// Limpieza de datos
function limpiarDatos(datos) {
  return {
    nombre: datos.nombre.trim().replace(/\s+/g, ' '),
    email: datos.email.toLowerCase().trim(),
    telefono: datos.telefono.replace(/\D/g, ''),
    categoria: datos.categoria.toLowerCase().trim(),
    experiencia: parseInt(datos.experiencia) || 0,
    precio_hora: parseFloat(datos.precio_hora) || 0,
    descripcion: datos.descripcion ? datos.descripcion.trim() : '',
    disponibilidad: datos.disponibilidad || 'flexible',
    ubicacion: datos.ubicacion ? datos.ubicacion.trim() : '',
    certificaciones: datos.certificaciones || [],
    idiomas: datos.idiomas || ['español']
  };
}

// Asistencia inteligente para completar datos
function asistenciaInteligente(datos) {
  const sugerencias = {};

  // Sugerir precio basado en categoría y experiencia
  if (!datos.precio_hora || datos.precio_hora === 0) {
    const preciosBase = {
      'plomeria': 800,
      'electricidad': 1000,
      'construccion': 1200,
      'pintura': 600,
      'jardineria': 500,
      'limpieza': 400,
      'mecanica': 900,
      'otros': 700
    };

    const base = preciosBase[datos.categoria] || 700;
    const experienciaBonus = datos.experiencia * 50;
    sugerencias.precio_hora_sugerido = base + experienciaBonus;
  }

  // Sugerir descripción basada en categoría
  if (!datos.descripcion || datos.descripcion.length < 20) {
    const descripciones = {
      'plomeria': 'Profesional especializado en instalaciones, reparaciones y mantenimiento de sistemas de plomería residenciales y comerciales.',
      'electricidad': 'Técnico certificado en instalaciones eléctricas, reparaciones y mantenimiento de sistemas residenciales y comerciales.',
      'construccion': 'Experto en construcción y remodelación, con experiencia en proyectos residenciales y comerciales.',
      'pintura': 'Profesional especializado en pintura interior y exterior, preparación de superficies y acabados de calidad.',
      'jardineria': 'Especialista en diseño y mantenimiento de jardines, poda de árboles y cuidado de áreas verdes.',
      'limpieza': 'Servicios de limpieza profesional para hogares y oficinas, con productos ecológicos y equipo especializado.',
      'mecanica': 'Mecánico automotriz certificado, especializado en diagnóstico, reparación y mantenimiento de vehículos.',
      'otros': 'Profesional con experiencia en servicios especializados, comprometido con la calidad y satisfacción del cliente.'
    };

    sugerencias.descripcion_sugerida = descripciones[datos.categoria] || descripciones.otros;
  }

  // Sugerir certificaciones basadas en categoría
  const certificacionesSugeridas = {
    'electricidad': ['Certificado de Electricista', 'Seguridad Eléctrica'],
    'plomeria': ['Certificado de Plomero', 'Instalaciones Sanitarias'],
    'construccion': ['Licencia de Constructor', 'Seguridad en Construcción'],
    'mecanica': ['Certificado ASE', 'Diagnóstico Automotriz']
  };

  if (certificacionesSugeridas[datos.categoria] && (!datos.certificaciones || datos.certificaciones.length === 0)) {
    sugerencias.certificaciones_sugeridas = certificacionesSugeridas[datos.categoria];
  }

  return sugerencias;
}

// Procesamiento principal
const datosLimpios = limpiarDatos(profesional);
const validacion = validarConIA(datosLimpios);
const sugerencias = asistenciaInteligente(datosLimpios);

// Preparar objeto final
const profesionalProcesado = {
  ...datosLimpios,
  validacion,
  sugerencias,
  fecha_registro: new Date().toISOString(),
  status: validacion.esValido ? 'pendiente_aprobacion' : 'requiere_correccion',
  score_calidad: calcularScoreCalidad(datosLimpios, validacion)
};

function calcularScoreCalidad(datos, validacion) {
  let score = 0;

  // Puntos por datos completos
  if (datos.descripcion && datos.descripcion.length > 50) score += 20;
  if (datos.experiencia > 5) score += 15;
  if (datos.precio_hora > 0) score += 10;
  if (datos.ubicacion) score += 10;
  if (datos.certificaciones && datos.certificaciones.length > 0) score += 15;
  if (datos.idiomas && datos.idiomas.length > 1) score += 10;

  // Puntos por validación
  if (validacion.esValido) score += 20;

  return Math.min(score, 100);
}

return { json: profesionalProcesado };

